package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var partFileLines []string
var partFileIdx int
var partRec PartRec

func init() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatInt(v int64, width int) string {
	// unedited numeric display: zero-padded, keep low-order digits if overflow
	neg := v < 0
	if neg {
		v = -v
	}
	s := fmt.Sprintf("%d", v)
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	if neg {
		// COBOL would show sign? not needed for this program
		// but keep consistent: put '-' in front if needed (not tested)
		// For width, we already padded; just prefix? We'll ignore as counts never negative.
	}
	return s
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx >= 0 {
		return s[:idx]
	}
	return s
}

func delimitedBySizeNumeric(v int64, width int) string {
	return formatInt(v, width)
}

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT PART-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty (COBOL would error, but for test harness allow empty)
		if os.IsNotExist(err) {
			partFileLines = []string{}
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines; increase buffer
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// Remove trailing \r if present (handle CRLF)
			if strings.HasSuffix(line, "\r") {
				line = strings.TrimSuffix(line, "\r")
			}
			partFileLines = append(partFileLines, line)
		}
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		f.Close()
	}
	partFileIdx = 0

	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE PART-FILE (already closed, nothing to do)
	SUMMARY_PARA()
}

func READ_PARA() {
	if partFileIdx >= len(partFileLines) {
		WsEofFlag = "Y"
		return
	}
	line := partFileLines[partFileIdx]
	partFileIdx++
	// COBOL LINE SEQUENTIAL: if line shorter than record length, pad with spaces
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// Parse 0:8, 8:3, 11:4
	lbPart := line[0:8]
	lbRegion := line[8:11]
	lbSerialStr := line[11:15]

	var lbSerial int64
	// Parse digits; if spaces treat as 0
	trimmed := strings.TrimSpace(lbSerialStr)
	if trimmed == "" {
		lbSerial = 0
	} else {
		// digits only, may contain leading zeros
		var v int64
		for _, ch := range lbSerialStr {
			if ch >= '0' && ch <= '9' {
				v = v*10 + int64(ch-'0')
			}
		}
		lbSerial = v
		// Keep low-order digits that fit in 4 digits? But value stored as int, STRING will re-pad
		// Overflow: keep low 4 digits value mod 10000
		if len(trimmed) > 4 {
			// already truncated by record length, but if numeric overflow, keep low order
		}
		if lbSerial > 9999 {
			lbSerial = lbSerial % 10000
		}
	}
	partRec.LbPart = lbPart
	partRec.LbRegion = lbRegion
	partRec.LbSerial = lbSerial
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := int64(strings.Count(partRec.LbPart, "A"))
	WsACount = cnt
	// STRING LB-REGION DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-PART DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-SERIAL DELIMITED BY SIZE
	//     INTO WS-LABEL
	// Build pieces
	p1 := delimitedBySpace(partRec.LbRegion)
	p2 := "-"
	p3 := delimitedBySpace(partRec.LbPart)
	p4 := "-"
	p5 := delimitedBySizeNumeric(partRec.LbSerial, 4)

	// Concatenate in order
	concat := p1 + p2 + p3 + p4 + p5
	// INTO WS-LABEL: place from left, pad/truncate to 20
	// STRING does not clear target, we already blanked, so overlay concat and leave rest as spaces
	if len(concat) > 20 {
		concat = concat[:20]
	}
	// Build WsLabel: concat + spaces remaining
	WsLabel = concat + strings.Repeat(" ", 20-len(concat))

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA += WsACount
	// ADD 1 TO WS-COUNT
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WsLabel is PIC X(20) -> print exactly 20 chars
	// WsACount is PIC 99 -> zero-padded 2
	out := WsLabel + " A=" + formatInt(WsACount, 2)
	fmt.Println(out)

	// PERFORM READ-PARA
	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	out := "LABELS: " + formatInt(WsCount, 3) + " A-TOTAL: " + formatInt(WsTotalA, 3)
	fmt.Println(out)
}
